const chatId = $('When Called by Another Workflow').first().json.chatId;

// ── n8n Workflows ──
let workflows = [];
try {
  const wfData = $('Fetch n8n Workflows').first().json;
  workflows = wfData?.data ?? wfData?.workflows ?? [];
} catch(e) {}
const totalWF = workflows.length;
const activeWF = workflows.filter(w => w.active).length;

// ── n8n Executions ──
let executions = [];
try {
  const exData = $('Fetch n8n Executions').first().json;
  executions = exData?.data ?? exData?.executions ?? [];
} catch(e) {}
const now = Date.now();
const recent24h = executions.filter(e => (now - new Date(e.startedAt ?? e.created_at ?? 0).getTime()) < 86400000).length;
const failedCount = executions.filter(e => e.status === 'error' || e.status === 'failed').length;
const successCount = executions.filter(e => e.status === 'success').length;

// ── Prometheus Alerts ──
let firingAlerts = 0;
let alertNames = [];
try {
  const alertData = $('Fetch Prometheus Alerts').first().json;
  const alerts = alertData?.data?.alerts ?? [];
  const firing = alerts.filter(a => a.state === 'firing');
  firingAlerts = firing.length;
  alertNames = firing.map(a => a.labels?.alertname ?? 'Unknown').slice(0, 3);
} catch(e) {}

// ── Crew API ──
let crews = [];
try {
  const crewData = $('Fetch Crew API').first().json;
  crews = Array.isArray(crewData) ? crewData : [];
} catch(e) {}
const totalAgents = crews.reduce((s, c) => s + (c.agents ?? 0), 0);

// ── Content Pieces ──
let pieces = [];
try {
  const pData = $('Fetch Content Pieces').first().json;
  pieces = pData?.list ?? [];
} catch(e) {}
const draftCount = pieces.filter(p => p.status === 'draft').length;
const publishedCount = pieces.filter(p => p.status === 'published').length;

// ── Status Icon ──
const statusIcon = firingAlerts > 0 ? '🔴' : failedCount > 3 ? '🟡' : '🟢';
const statusText = firingAlerts > 0 ? 'Alarm' : failedCount > 3 ? 'Warnung' : 'OK';

const ts = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit' });

let report = `${statusIcon} *AIOS System Status* — ${statusText}\n`;
report += `_Stand: ${ts} Uhr_\n\n`;

report += `*n8n Workflows:*\n`;
report += `• ${activeWF} aktiv | ${totalWF - activeWF} pausiert | ${totalWF} gesamt\n\n`;

report += `*Ausführungen (letzte 50):*\n`;
report += `• 24h: ${recent24h} | ✅ ${successCount} | ❌ ${failedCount}\n\n`;

report += `*Crew AI:*\n`;
if (crews.length > 0) {
  report += `• ${crews.length} Crews | ${totalAgents} Agents | ${pieces.length} Pieces\n`;
  report += `• Drafts: ${draftCount} | Published: ${publishedCount}\n`;
} else {
  report += `• Crew API nicht erreichbar\n`;
}
report += `\n`;

report += `*Prometheus:*\n`;
if (firingAlerts === 0) {
  report += `• ✅ Keine feuernden Alerts\n`;
} else {
  report += `• 🔴 ${firingAlerts} Alert(s):\n`;
  alertNames.forEach(name => { report += `  - ${name}\n`; });
}

return [{ json: { chatId, response: report } }];
